import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import "./App.css";
import NavigationBar from "./components/NavigationBar";
import InputMeal from "./components/InputMeal";
import SearchFood from "./components/SearchFood";
import DailyGoals from "./components/DailyGoals";
import WeeklyReports from "./components/WeeklyReports";
import Suggestions from "./components/Suggestions";

// Placeholder components for Auth and Calendar pages
const AuthPage = () => <div>Auth Page</div>;
const CalendarPage = () => <div>Calendar Page</div>;

// Error boundary component to handle rendering errors
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error) {
    // Update state to indicate an error occurred
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // Log the error details for debugging
    console.log(error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      // Return a fallback UI if an error occurred
      return <h1>Something went wrong.</h1>;
    }

    return this.props.children;
  }
}

function App() {
  return (
    <Router>
      <div className="App">
        <NavigationBar />
        <Routes>
          <Route
            path="/"
            element={
              <ErrorBoundary>
                <div className="dashboard">
                  <div className="top-section">
                    <InputMeal />
                    <SearchFood />
                  </div>
                  <div className="bottom-section">
                    <DailyGoals />
                    <WeeklyReports />
                    <Suggestions />
                  </div>
                </div>
              </ErrorBoundary>
            }
          />
          <Route path="/auth" element={<AuthPage />} />
          <Route path="/calendar" element={<CalendarPage />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
